        kind: isIndexer ? 'indexer' : 'property',
        name: lastName ?? '<anon>',
        startLine,
        endLine: Math.max(endLine, startLine),
        modifiers,
        attributes,
        bases: [],
        implements: [],
        params: [],
        body: [],
